    // RenderThread may still own the last drawn hardware buffer.
    // Release only after removal commits or the bounded one-shot fallback.
    if(!old.drawn || !host.isAttachedToWindow){old.release();return}
    val observer=host.viewTreeObserver
    var callback:Runnable?=null
    val release=Runnable{
        callback?.let{cb->runCatching{if(observer.isAlive)observer.unregisterFrameCommitCallback(cb)}}
        old.release()
    }
    callback=Runnable{ui.removeCallbacks(release);ui.post(release)}
    runCatching{if(observer.isAlive)observer.registerFrameCommitCallback(checkNotNull(callback))}
    ui.postDelayed(release,200L)
    host.invalidate()
}
fun finish(result:String){
    if(!current())return
    capturePermit.revoke()
    active=null
    waitingCapture=false;waitingCommit=false

}

/** One attempt's worker-only permission. Owner revocation cannot interrupt an
 * already entered capture; all later stages recheck before starting. The
 * existing owner validity/commit gates still control publication and moves. */
internal class StageTapCapturePermit {
    private val cancelled=java.util.concurrent.atomic.AtomicBoolean(false)
    val revoked:Boolean get()=cancelled.get()
    fun revoke(){cancelled.set(true)}
    fun allows(now:Long,deadline:Long):Boolean = !revoked &&
        StageTransientTapPolicy.canCaptureSecond(now,deadline)
}
